:root{--color-bg:#f6faf9;--color-surface:#ffffff;--color-text:#1b2b2e;--color-text-muted:#44595c;--color-primary-dark:#0b5566;--color-primary-dark-hover:#083f4c;--color-dark-bg:#0b3d4a;--color-accent-on-dark:#ffd27a;--color-border:#d7e4e2;--font-base:Georgia, 'Times New Roman', serif;--font-heading:Georgia, 'Times New Roman', serif;--space-xs:0.5rem;--space-sm:1rem;--space-md:1.5rem;--space-lg:2.5rem;--space-xl:4rem;--radius:0.5rem;--max-width:75rem;}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{margin:0;font-family:var(--font-base);background-color:var(--color-bg);color:var(--color-text);line-height:1.6;}
h1,h2,h3{font-family:var(--font-heading);line-height:1.25;color:var(--color-primary-dark);margin-top:0;}
p{margin-top:0;margin-bottom:var(--space-sm);}
a{color:var(--color-primary-dark);text-decoration:underline;}
a:hover{color:var(--color-primary-dark-hover);}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--color-accent-on-dark);outline-offset:2px;}
.container{max-width:var(--max-width);margin:0 auto;padding:0 1.25rem;width:100%;}
/* Header */
header{background-color:var(--color-surface);border-bottom:1px solid var(--color-border);}
.header-inner{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:var(--space-sm);padding-top:var(--space-sm);padding-bottom:var(--space-sm);}
.logo{font-family:Rockwell, 'Courier New', Georgia, serif;font-weight:bold;font-style:italic;text-transform:uppercase;letter-spacing:0.08em;font-size:clamp(1.1rem,4vw,1.6rem);color:var(--color-primary-dark);text-shadow:3px 3px 0 var(--color-dark-bg);text-decoration:none;}
.logo:hover{color:var(--color-primary-dark-hover);}
.nav-list{list-style:none;display:flex;flex-wrap:wrap;gap:var(--space-sm);margin:0;padding:0;}
.nav-list a{text-decoration:none;color:var(--color-text);font-weight:bold;padding:0.4rem 0.2rem;}
.nav-list a:hover{color:var(--color-primary-dark);}
/* Footer */
footer{background-color:var(--color-dark-bg);color:var(--color-accent-on-dark);margin-top:var(--space-xl);}
.footer-inner{padding:var(--space-lg) 1.25rem;text-align:center;}
.footer-name{font-weight:bold;font-size:1.1rem;margin-bottom:var(--space-xs);}
.footer-copy{margin-top:var(--space-sm);font-size:0.9rem;opacity:0.9;}
footer a{color:var(--color-accent-on-dark);}
/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0.75rem 1.5rem;border-radius:var(--radius);border:2px solid var(--color-primary-dark);background-color:var(--color-primary-dark);color:#ffffff;font-weight:bold;font-size:1rem;text-decoration:none;cursor:pointer;}
.btn:hover{background-color:var(--color-primary-dark-hover);border-color:var(--color-primary-dark-hover);}
.btn-secondary{background-color:transparent;color:var(--color-primary-dark);}
.btn-secondary:hover{background-color:var(--color-primary-dark);color:#ffffff;}
/* Cards */
.card{background-color:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius);padding:var(--space-md);}
/* Grid helper */
.grid{display:grid;grid-template-columns:1fr;gap:var(--space-md);}
/* Forms */
form{display:flex;flex-direction:column;gap:var(--space-md);}
.form-group{display:flex;flex-direction:column;gap:0.35rem;}
label{font-weight:bold;}
input[type=text],input[type=email],input[type=tel],input[type=date],select,textarea{min-height:44px;padding:0.6rem 0.8rem;border:1px solid var(--color-border);border-radius:var(--radius);font-family:inherit;font-size:1rem;background-color:var(--color-surface);color:var(--color-text);}
textarea{min-height:110px;}
fieldset{border:1px solid var(--color-border);border-radius:var(--radius);padding:var(--space-md);}
legend{font-weight:bold;padding:0 0.4rem;color:var(--color-primary-dark);}
.checkbox-row{display:flex;align-items:center;gap:0.5rem;}
.checkbox-row input{width:1.25rem;height:1.25rem;}
section{padding:var(--space-lg) 0;}
/* Mobile */
@media (max-width:600px){
  .header-inner{flex-direction:column;align-items:flex-start;}
  .nav-list{flex-direction:column;gap:0.5rem;width:100%;}
  .grid{grid-template-columns:1fr;}
  .logo{font-size:1.2rem;}
}
/* Desktop */
@media (min-width:601px){
  .grid-2{grid-template-columns:repeat(2,1fr);}
  .grid-3{grid-template-columns:repeat(3,1fr);}
  .header-inner{flex-wrap:nowrap;}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto;}
  *{animation:none !important;transition:none !important;}
}

pages.css:
.index-hero{background-color:var(--color-dark-bg);color:var(--color-accent-on-dark);padding:var(--space-xl) 0;}
.index-hero-inner{text-align:center;max-width:42rem;}
.index-hero-eyebrow{font-weight:bold;letter-spacing:0.05em;margin-bottom:var(--space-xs);}
.index-hero-heading{color:#ffffff;font-size:clamp(1.6rem,4vw,2.4rem);margin-bottom:var(--space-sm);}
.index-hero-inner p{color:var(--color-accent-on-dark);}
.index-details{background-color:var(--color-surface);border-top:1px solid var(--color-border);border-bottom:1px solid var(--color-border);}
.index-bring{background-color:var(--color-surface);border-top:1px solid var(--color-border);border-bottom:1px solid var(--color-border);}
.index-schedule-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:var(--space-sm);}
.index-schedule-list li{display:flex;gap:var(--space-sm);align-items:baseline;border-bottom:1px solid var(--color-border);padding-bottom:var(--space-sm);}
.index-schedule-time{font-weight:bold;color:var(--color-primary-dark);min-width:5.5rem;flex-shrink:0;}
.index-testimonial{margin:0;}
.index-testimonial p{font-style:italic;}
.index-testimonial footer{color:var(--color-text-muted);font-size:0.95rem;}
.index-signup{background-color:var(--color-bg);}
.index-signup-form{max-width:40rem;margin:0 auto;}
.index-faq-list{display:flex;flex-direction:column;gap:var(--space-sm);}
.index-faq-item summary{cursor:pointer;font-weight:bold;color:var(--color-primary-dark);}
.index-faq-item p{margin-top:var(--space-sm);margin-bottom:0;}
@media (max-width:600px){
  .index-schedule-list li{flex-direction:column;gap:0.25rem;}
  .index-schedule-time{min-width:0;}
  .index-hero{padding:var(--space-lg) 0;}
}
@media (min-width:601px){
  .index-hero-inner{margin-left:auto;margin-right:auto;}
}

